import { formatDateToQuarterYear } from 'utils/format';

export type SlidePeriodType = 'LQ' | 'YTD';

const SLIDE_APOSTROPHE = "'";

interface PeriodFields {
  slideLabel: string;
  coverPrefix: string;
  coverYear: string;
  coverFallback: string;
  label: string;
}

const EMPTY_FIELDS: PeriodFields = {
  slideLabel: '',
  coverPrefix: '',
  coverYear: '',
  coverFallback: '',
  label: '',
};

export class Period {
  readonly slideLabel: string;
  readonly coverPrefix: string;
  readonly coverYear: string;
  readonly coverFallback: string;
  readonly label: string;
  readonly normalized: string;
  readonly isYtd: boolean;

  private constructor(date: Date | undefined, type: SlidePeriodType) {
    this.isYtd = type === 'YTD';
    this.normalized = type === 'LQ' ? 'QTD' : type;

    const fields = Period.buildFields(date, this.isYtd);
    this.slideLabel = fields.slideLabel;
    this.coverPrefix = fields.coverPrefix;
    this.coverYear = fields.coverYear;
    this.coverFallback = fields.coverFallback;
    this.label = fields.label;
  }

  static from(date: Date | undefined, type: SlidePeriodType = 'LQ'): Period {
    return new Period(date, type);
  }

  static normalize(type?: string, fallback?: string): string | undefined {
    if (!type) return fallback;
    const upper = type.toUpperCase();
    return upper === 'LQ' ? 'QTD' : upper;
  }

  private static buildFields(
    date: Date | undefined,
    isYtd: boolean,
  ): PeriodFields {
    if (!date) return EMPTY_FIELDS;

    const quarterYearFull = formatDateToQuarterYear(date, ' ', 0);
    const [quarter, year] = quarterYearFull.split(' ');
    const shortYear = year?.slice(-2) ?? '';

    return isYtd
      ? Period.buildYtdFields(shortYear, year ?? '')
      : Period.buildQuarterFields(
          date,
          quarter ?? '',
          year ?? '',
          quarterYearFull,
        );
  }

  private static buildYtdFields(shortYear: string, year: string): PeriodFields {
    return {
      slideLabel: shortYear ? `YTD${SLIDE_APOSTROPHE}${shortYear}` : '',
      coverPrefix: 'YTD',
      coverYear: year,
      coverFallback: year ? `YTD ${year}` : '',
      label: shortYear ? `YTD'${shortYear}` : '',
    };
  }

  private static buildQuarterFields(
    date: Date,
    quarter: string,
    year: string,
    quarterYearFull: string,
  ): PeriodFields {
    const quarterYear = formatDateToQuarterYear(date, SLIDE_APOSTROPHE);
    return {
      slideLabel: quarterYear,
      coverPrefix: quarter,
      coverYear: year,
      coverFallback: quarterYearFull,
      label: quarterYear,
    };
  }
}
